package com.blog.entity; import jakarta.persistence.*; import lombok.*; import java.util.*;
@Entity @Table(name="categories",uniqueConstraints=@UniqueConstraint(columnNames="name")) @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder public class Category { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,length=80) private String name; @Column(length=500) private String description; @OneToMany(mappedBy="category") private List<Post> posts=new ArrayList<>(); }
